import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"8、【比】 坤下坎上","description":"周易尚氏学 - 8、【比】 坤下坎上","frontmatter":{"title":"8、【比】 坤下坎上","description":"周易尚氏学 - 8、【比】 坤下坎上"},"headers":[],"relativePath":"zh/classics/shangshi/013.md","filePath":"zh/classics/shangshi/013.md"}'),s={name:"zh/classics/shangshi/013.md"};function h(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_8、【比】-坤下坎上" tabindex="-1">8、【比】 坤下坎上 <a class="header-anchor" href="#_8、【比】-坤下坎上" aria-label="Permalink to “8、【比】 坤下坎上”">​</a></h1><p>比亲也。辅也。坎坤同舍于子。故曰比。唐以前。先天象失传。故卦名不得解。清毛大可黄宗义等知之而之认。后学不察。相率以言先天为戒。而自命为汉易。岂知康成注月令。于季夏云。未属巽辰。又在巽位。巽若不在西南。未能在巽位乎。是先天方位。郑且明言之。九家注同人云。乾舍于离。与日同居。荀爽注同人云。乾舍于离。相与同居。注阴阳之义配日月云。乾舍于离。配日而居。坤舍于坎。配月而居。已一再言之乎。比之义即以坎坤同居也。原者田也。左传僖二十八年。原田每每。注高平曰原。周礼太卜原兆注。原原田也。按古皆井田。每每者。井与井相间之形。坤为拆。象原田。故曰原筮。坎为筮。坤为原。原筮。犹言野筮也。曲礼云。外事以刚日。郑注。外事郊外之事。仪礼士丧礼。筮于兆域。兆域在郊外。即原筮也。而乾宝因周礼三卜。一曰原兆。即训原为卜。可谓大谬。按周礼。太卜掌三兆之法。一曰玉兆。二曰瓦兆。三日原兆。注。言龟兆似玉瓦原之璺鏬。然则原者原田。田必有璺鏬。象龟兆之形。故曰原兆。岂以原为卜乎。故原指坤。于训卜固非。孔颖达谓原为原究。朱子谓原为再。王夫之谓原为本。俞樾谓原为始。为本。益浮泛不切。故夫说易而不求象。未有能当者也。元谓九五。永贞者永定也。坤为乱。故曰不宁。方。诗小雅方舟为梁。汉书韩信传云。今井陉之道。车不得方轨。注皆训方为并。方来。谓下四阴并来归五也。旧解不求卦象。训方为将。为四方。皆失之。艮为夫。上六独居艮后。故曰后夫。下四阴皆承阳。独上六乘阳不顺。故凶。此卦因原象筮象夫象失传。故自汉迄今。无得解者。</p><p>彖曰。比。吉也。比。辅也。下顺从也。原筮元永贞无咎。以刚中也。不宁方来。上下应也。后夫凶。其道穷也。</p><p>上谓五。下谓四阴。上六居卦之极。故曰道穷。</p><p>象曰。地上有水。比。先王以建万国。亲诸侯。</p><p>先王谓五。坤为万国。国必建侯。坤多故曰诸侯。五南面称尊。抚临天下。故王者取以为法。亲即比也。</p><p>初六。有孚比之。无咎。有孚盈缶。终来有它。吉。</p><p>坎为孚。五为卦主。故亦孚于初而比之。初失位。本有咎。比五故无咎。坤为缶。初居缶之最下。去五虽远。然坎雨下注。始于四。以次及初。至初而缶盈矣。故曰有孚盈缶。阳性上升。五升上剥。剥穷上反下。则初阳复矣。故曰来。以其有待。故曰终来。有它谓有应于他方也。大过九四曰有它吝。谓应初也。中孚初九曰有它不燕。谓应四也。此两卦皆有应。而皆不吉者。以得敌为害也。故不安。故吝。此曰有它吉者。以阳来反初。当位有应。故吉。荀爽以非应释有它，清易家多从之。岂知大过中孚皆有应。而亦曰有它。则夫有它之不指非应甚明。虞翻谓初动成屯得正故吉。岂知此谓之变。不谓之来。更不得谓之终来。曰终来。固确有所指。且果如虞说。初动之正。乃初爻自变。益不得谓之有它。理甚明矣。虞亦知其说之有鏬。复申曰在内称来。夫爻在外曰往。在内曰来。如需讼之往来得中。否泰之大小往来。皆是。兹曰终来。若仅在内称来。复何有始终之可言乎。失经旨矣。它古蛇字。易林以坤为它。损之比云。大它当路。使季畏惧。以比下坤为它。不读为谁他之他。系辞云。龙它之蛰。以存身也。龙为乾。它为坤。言蛰于戍亥也。林所本也。而巽亦为蛇。故大过九四。中孚初九。亦曰有它。后儒颇有用焦说者又一义也。</p><h3 id="象曰。比之初六。有它吉也。" tabindex="-1">象曰。比之初六。有它吉也。 <a class="header-anchor" href="#象曰。比之初六。有它吉也。" aria-label="Permalink to “象曰。比之初六。有它吉也。”">​</a></h3><p>六二。比之自内。贞吉。</p><p>二应五。故曰自内。言自内比五也。二当位中正。故曰贞吉。</p><h3 id="象曰。比之自内。不自失也。" tabindex="-1">象曰。比之自内。不自失也。 <a class="header-anchor" href="#象曰。比之自内。不自失也。" aria-label="Permalink to “象曰。比之自内。不自失也。”">​</a></h3><p>言自内比五。不敢安逸也。失通佚。诸家作得失诂。非。</p><p>六三。比之匪人。</p><p>虞氏逸象乾为人。六三不当位无应。承乘皆阴。行失类。故曰比之匪人。言不得阳也。</p><h3 id="象曰。比之匪人。不亦伤乎。" tabindex="-1">象曰。比之匪人。不亦伤乎。 <a class="header-anchor" href="#象曰。比之匪人。不亦伤乎。" aria-label="Permalink to “象曰。比之匪人。不亦伤乎。”">​</a></h3><p>三独失实。故可伤。</p><p>六四。外比之贞吉。</p><p>四承五。外比即从上。贞吉者。卜问则吉也。</p><h3 id="象曰。外比于贤。" tabindex="-1">象曰。外比于贤。 <a class="header-anchor" href="#象曰。外比于贤。" aria-label="Permalink to “象曰。外比于贤。”">​</a></h3><p>以从上也。阳为贤指五。</p><p>九五。显比。王用三驱。失前禽。邑人不诫。吉。</p><p>九五伏离。当阳得位。向明而治。故曰显比。王谓五。三驱猎礼也。汉书五行志。田狩有三驱之制。注。三驱之礼。一为乾豆。二为宾客。三为君庖。又晋书五行志。登车有三驱之制。又刘聪传。校猎上林。将军负戟前导。行三驱之礼。艮数三。故曰三驱。前禽谓下四阴。上为后。故知前为下。失逸古通。逸前禽者。喻人皆来比。无所诛杀。任其逸也。坤为邑。不诫谓王师宽大。所至之邑。百姓仍安居乐业。人人亲附。不惊诫也。说文诫敕也。广韵言警也。左传桓十一年。郧人军其郊。必不诫。言无备虞也。</p><h3 id="象曰。显比之吉。位正中也。舍逆取顺。失前禽也。邑人不诫。上使中也。" tabindex="-1">象曰。显比之吉。位正中也。舍逆取顺。失前禽也。邑人不诫。上使中也。 <a class="header-anchor" href="#象曰。显比之吉。位正中也。舍逆取顺。失前禽也。邑人不诫。上使中也。" aria-label="Permalink to “象曰。显比之吉。位正中也。舍逆取顺。失前禽也。邑人不诫。上使中也。”">​</a></h3><p>九五中正。故显。逆迎也。下四阴皆逆我者也。逆而来归。理应舍之。故曰逸前禽。如纣师之倒戈归周是也。王注禽顺行背我而走者。则射而取之。按顺行与我同向。同向即背我。上六是也。故取之。此四字只王注得解。虞翻谓舍逆指上六。前禽指初。岂知后夫如得舍。尚何云凶。初有孚盈缶。即孚于五。又安得独不及初。而后儒皆从之。异已。上使中者。言五所遣师徒。合乎中道。故无过举。得不诫也。唐郭京举正。称得辅嗣真本。以舍逆取顺。在失前禽下。朱芹引李清植曰。考象传。屡以禽与东部字韵。屯三爻禽与穷韵。恒四爻禽与容韵。此又与中韵。郭京所改。显失易韵。今按诗小雅呦呦鹿鸣。食野之芩。韵与此同。焦氏易林用韵如此者尤多。而履之夬以禽与功韵。与象传尤符。盖古音原如此。今晋人读禽为轻。正与古音合。郭京所称辅嗣本。无论真伪。不可从也。</p><p>上六。比之无首。凶。</p><p>坎为首。首谓五也。而五为坎主。上六乘阳。首为所蔽。故曰无首。大过上六曰灭顶凶。既济上六曰。濡其首。与此义同也。而复于此爻。更曰反君道。无首即反君道。反君故凶。荀虞皆不知首指五。故说皆不切。清惠士奇更实指曰首指上。谓木一在下为本。一在上为末。末即首。意谓上六为末爻。故为首也。说尤穿凿。</p><h3 id="象曰。比之无首。无所终也。" tabindex="-1">象曰。比之无首。无所终也。 <a class="header-anchor" href="#象曰。比之无首。无所终也。" aria-label="Permalink to “象曰。比之无首。无所终也。”">​</a></h3><p>道穷故无所终。</p>',29)])])}const f=e(s,[["render",h]]);export{_ as __pageData,f as default};
